func init() {
	func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Fprintln(os.Stderr, "gowt/internal/win32: deferred init Gdip static{}:", r)
			}
		}()
	LibraryLoadLibrary("swt-gdip")
	}()
}

